sys_script_include.script:
var LabTestUtilsClient = Class.create();
LabTestUtilsClient.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    getLabTestDetails: function () {
        var lab = new GlideRecord('u_lab_test');
        if (lab.get(this.getParameter('sysparm_lab_test_id'))) {
            return JSON.stringify({
                test_name: lab.getValue('u_test_name'),
                result: lab.getValue('u_result'),
                status: lab.getValue('u_status')
            });
        }
        return JSON.stringify({error: "Lab Test not found"});
    }
});
